using System;using System.IO;using System.Linq;using System.Collections.Generic;using Autodesk.AutoCAD.ApplicationServices;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.PlottingServices;using Elevator.AutoCAD;using Elevator.Core.Geometry;
public sealed class AAPlot {
 [CommandMethod("AAPLOT")]public void Plot(){var doc=Application.DocumentManager.MdiActiveDocument;var db=doc.Database;using(var tr=db.TransactionManager.StartTransaction()){var all=SectionAADrawing.Find(db,tr);var f=SectionAADrawing.Frame(all);var d=ProjectDataStorage.Read<SectionAAProject>(db,tr,SectionAADrawing.DataKey);SectionSnapshot bb;var s=VerticalExperimentDrawing.ReadSource(db,tr,out bb);var g=SectionAACalculator.Calculate(d,s.Section.Reference.SourceSlabThickness);var windows=new Dictionary<string,double[]>();string mode=Environment.GetEnvironmentVariable("AA_PLOT_MODE")??"clean";double car=-s.Plan.CarRow,cw=-s.Plan.CwRow;
 if(mode=="clean"){windows.Add("01_clean_master_full",new[]{-3700.0,g.PitZ-2300,4700,g.Ceiling+1400});windows.Add("02_clean_floor_module",new[]{-s.Plan.SD-400,5500.0,3000,8600});windows.Add("03_clean_car",new[]{-s.Plan.SD-150,g.CarZ-200,450,g.CarZ+2450});windows.Add("04_clean_cw",new[]{cw-350,g.CWBottom-150,cw+650,g.CWBottom+3150});}
 else if(mode=="nostop")windows.Add("08_auto_no_stop",new[]{-s.Plan.SD-400,d.Floors[2].FflZ-400,4700,d.Floors[2].FflZ+2500});
 else if(mode=="unequal")windows.Add("12_auto_unequal_floors",new[]{-3700.0,g.PitZ-2300,4700,g.Ceiling+1400});
 else{windows.Add("05_auto_full_section",new[]{-3700.0,g.PitZ-2300,4700,g.Ceiling+1400});windows.Add("06_auto_pit",new[]{-s.Plan.SD-400,g.PitZ-850,2300,500.0});windows.Add("07_auto_typical_floor",new[]{-s.Plan.SD-400,d.Floors[1].FflZ-400,3000,d.Floors[1].FflZ+2500});windows.Add("09_auto_car_cw",new[]{-s.Plan.SD-400,g.CarZ-200,450,g.CWBottom+3150});windows.Add("10_auto_overhead",new[]{-s.Plan.SD-400,g.Floors.Where(v=>v.Served).Last().FflZ-400,4700,g.R+200});windows.Add("11_auto_machine_room",new[]{-s.Plan.SD-550,g.R-400,3000,g.Ceiling+1400});}
 var layout=(Layout)tr.GetObject(LayoutManager.Current.GetLayoutId(LayoutManager.Current.CurrentLayout),OpenMode.ForRead);
 foreach(var pair in windows){using(var ps=new PlotSettings(layout.ModelType))using(var pi=new PlotInfo())using(var validator=new PlotInfoValidator()){ps.CopyFrom(layout);var v=PlotSettingsValidator.Current;v.SetPlotConfigurationName(ps,"DWG To PDF.pc3",null);v.RefreshLists(ps);v.SetCanonicalMediaName(ps,v.GetCanonicalMediaNameList(ps).Cast<string>().First(n=>n.Contains("A1")&&n.Contains("841")));var a=f.World(new Point3d(pair.Value[0],pair.Value[1],0));var b=f.World(new Point3d(pair.Value[2],pair.Value[3],0));v.SetPlotWindowArea(ps,new Extents2d(a.X,a.Y,b.X,b.Y));v.SetPlotType(ps,Autodesk.AutoCAD.DatabaseServices.PlotType.Window);v.SetUseStandardScale(ps,true);v.SetStdScaleType(ps,StdScaleType.ScaleToFit);v.SetPlotCentered(ps,true);v.SetPlotRotation(ps,PlotRotation.Degrees000);v.SetCurrentStyleSheet(ps,"monochrome.ctb");pi.Layout=layout.ObjectId;pi.OverrideSettings=ps;validator.MediaMatchingPolicy=MatchingPolicy.MatchEnabled;validator.Validate(pi);using(var engine=PlotFactory.CreatePublishEngine())using(var page=new PlotPageInfo()){engine.BeginPlot(null,null);engine.BeginDocument(pi,doc.Name,null,1,true,Path.Combine(SectionAADrawing.Output,pair.Key+".pdf"));engine.BeginPage(page,pi,true,null);engine.BeginGenerateGraphics(null);engine.EndGenerateGraphics(null);engine.EndPage(null);engine.EndDocument(null);engine.EndPlot(null);}}}
 }}
